import { createHash } from 'node:crypto'
import { describe, expect, it } from 'vitest'
import { boundInstructions } from '@omne-harness/mcp-contract'

const sha = (text: string) => `sha256:${createHash('sha256').update(text, 'utf8').digest('hex')}`

describe('boundInstructions', () => {
  it('keeps text within the bound whole', () => {
    expect(boundInstructions('use tools', 9)).toEqual({
      text: 'use tools',
      truncated: false,
      digest: sha('use tools'),
    })
  })

  it('cuts at the byte bound and digests the whole text before the cut', () => {
    expect(boundInstructions('abcdef', 4)).toEqual({
      text: 'abcd',
      truncated: true,
      digest: sha('abcdef'),
    })
  })

  it('does not split a character: a cut inside a multi-byte character drops all of it', () => {
    // 'é' is 2 bytes and '€' is 3 bytes in UTF-8.
    expect(boundInstructions('aé', 2).text).toBe('a')
    expect(boundInstructions('a€b', 3).text).toBe('a')
    expect(boundInstructions('a€b', 4).text).toBe('a€')
    expect(boundInstructions('€', 2)).toMatchObject({ text: '', truncated: true })
  })

  it('throws for a bound that is not a positive safe integer', () => {
    for (const bound of [0, -1, 1.5, Number.NaN])
      expect(() => boundInstructions('a', bound)).toThrow(RangeError)
  })
})

tests/json-equality.spec.ts.source:
import { describe, expect, it } from 'vitest'
import { writeJsonText } from '@omne-harness/json-text'
import { canonical, sameJson } from '@omne-harness/mcp-contract'
import { json, jsonText } from './json.ts'

describe('canonical and sameJson', () => {
  it('sorts object members by name at every depth and keeps number lexemes', () => {
    const tree = jsonText('{"b":{"y":1.0,"x":[{"d":2,"c":3}]},"a":null}')
    expect(writeJsonText(canonical(tree))).toBe('{"a":null,"b":{"x":[{"c":3,"d":2}],"y":1.0}}')
  })

  it('treats trees that differ only in member order as the same', () => {
    expect(sameJson(json({ a: 1, b: { c: 2, d: 3 } }), json({ b: { d: 3, c: 2 }, a: 1 }))).toBe(
      true,
    )
  })

  it('tells apart a different value, a different member and a different number lexeme', () => {
    expect(sameJson(json({ a: 1 }), json({ a: 2 }))).toBe(false)
    expect(sameJson(json({ a: 1 }), json({ a: 1, b: 1 }))).toBe(false)
    expect(sameJson(jsonText('{"a":1}'), jsonText('{"a":1.0}'))).toBe(false)
    expect(sameJson(json([1, 2]), json([2, 1]))).toBe(false)
  })
})
